from sqlalchemy import String,Integer,Float,DateTime,Text,JSON,ForeignKey,func
from sqlalchemy.orm import Mapped,mapped_column
from src.config.database import Base
class Stall(Base):
    __tablename__='stalls'; id:Mapped[int]=mapped_column(Integer,primary_key=True); code:Mapped[str]=mapped_column(String(30),unique=True,index=True); name:Mapped[str]=mapped_column(String(100)); category:Mapped[str]=mapped_column(String(50)); zone:Mapped[str]=mapped_column(String(50)); owner_name:Mapped[str]=mapped_column(String(80)); status:Mapped[str]=mapped_column(String(20),default='active'); avg_ticket:Mapped[float]=mapped_column(Float,default=0); occupancy_rate:Mapped[float]=mapped_column(Float,default=0); created_at:Mapped[object]=mapped_column(DateTime,server_default=func.now())
class CampaignWindow(Base):
    __tablename__='campaign_windows'; id:Mapped[int]=mapped_column(Integer,primary_key=True); code:Mapped[str]=mapped_column(String(30),unique=True,index=True); name:Mapped[str]=mapped_column(String(100)); label:Mapped[str]=mapped_column(String(80)); starts_at:Mapped[object]=mapped_column(DateTime); ends_at:Mapped[object]=mapped_column(DateTime); target_zone:Mapped[str]=mapped_column(String(50)); status:Mapped[str]=mapped_column(String(20),default='scheduled'); owner:Mapped[str]=mapped_column(String(80)); notes:Mapped[str]=mapped_column(Text,default='')
class FootfallSample(Base):
    __tablename__='footfall_samples'; id:Mapped[int]=mapped_column(Integer,primary_key=True); stall_id:Mapped[int]=mapped_column(ForeignKey('stalls.id'),index=True); campaign_window_id:Mapped[int|None]=mapped_column(ForeignKey('campaign_windows.id'),nullable=True); sampled_at:Mapped[object]=mapped_column(DateTime,index=True); window_label:Mapped[str]=mapped_column(String(30)); footfall:Mapped[int]=mapped_column(Integer); transactions:Mapped[int]=mapped_column(Integer); revenue:Mapped[float]=mapped_column(Float); dwell_seconds:Mapped[float]=mapped_column(Float); weather:Mapped[str]=mapped_column(String(30)); campaign_label:Mapped[str]=mapped_column(String(80),default=''); status:Mapped[str]=mapped_column(String(20),default='valid',index=True); issue_reason:Mapped[str]=mapped_column(String(255),default=''); source:Mapped[str]=mapped_column(String(50),default='counter-card'); notes:Mapped[str]=mapped_column(Text,default='')
class AnalysisRun(Base):
    __tablename__='analysis_runs'; id:Mapped[int]=mapped_column(Integer,primary_key=True); name:Mapped[str]=mapped_column(String(120)); status:Mapped[str]=mapped_column(String(30),default='queued',index=True); review_status:Mapped[str]=mapped_column(String(20),default='pending'); requested_by:Mapped[int]=mapped_column(ForeignKey('users.id')); sample_ids:Mapped[list]=mapped_column(JSON); sample_count:Mapped[int]=mapped_column(Integer,default=0); result:Mapped[dict|None]=mapped_column(JSON,nullable=True); review_note:Mapped[str]=mapped_column(Text,default=''); created_at:Mapped[object]=mapped_column(DateTime,server_default=func.now()); completed_at:Mapped[object|None]=mapped_column(DateTime,nullable=True)
class Brief(Base):
    __tablename__='briefs'; id:Mapped[int]=mapped_column(Integer,primary_key=True); analysis_id:Mapped[int]=mapped_column(ForeignKey('analysis_runs.id'),unique=True); title:Mapped[str]=mapped_column(String(160)); status:Mapped[str]=mapped_column(String(20),default='draft'); summary:Mapped[str]=mapped_column(Text); recommended_stalls:Mapped[list]=mapped_column(JSON); audience:Mapped[str]=mapped_column(String(100),default='招商委员会'); issued_by:Mapped[int|None]=mapped_column(ForeignKey('users.id'),nullable=True); created_at:Mapped[object]=mapped_column(DateTime,server_default=func.now()); issued_at:Mapped[object|None]=mapped_column(DateTime,nullable=True)
